mat2 matriceRotation2D(float angle) {
    float c = cos(angle), s = sin(angle);
    return mat2(c, -s, s, c);
}

vec3 deformationTorsion(vec3 p, float force) {
    float angle = p.z * force;
    mat2 rot = matriceRotation2D(angle);
    return vec3(rot * p.xy, p.z);
}

float distanceTore(vec3 p, float rMaj, float rMin) {
    vec2 proj = vec2(length(p.xy) - rMaj, p.z);
    return length(proj) - rMin;
}

float carteScene(vec3 position) {
    float temps = -iTime * 0.6;
    float pi = 3.14159265359;
    float tau = 6.28318530718;
    float pas = pi / 24.0;

    float bass = texture(iChannel0, vec2(0.02, 0.25)).x;
    float kick = pow(bass, 2.5) * 1.8;
    float mid = texture(iChannel0, vec2(0.35, 0.25)).x;

    float intensite = (0.003 + kick * 0.0015) * sin(iTime * 1.5);
    vec3 p = deformationTorsion(position, intensite);

    p.xz *= matriceRotation2D(-temps);
    p.xy *= matriceRotation2D(-temps / 3.0);

    float dMin = 1e5;

    for (int k = 0; k < 24; k++) {
        float i = float(k) * pas + temps;
        float angleRot = i / 33.0;

        float modFreq = (k % 2 == 0) ? kick : mid;
        float facteurCone = float(k) / 24.0;

        float expansionEvasement = 1.0 + kick * (0.35 + facteurCone * 0.5);
        float pulsionMembrane = 1.0 + modFreq * 0.2;

        float rMajeur = 30.0 * float(k) * pas * expansionEvasement;
        float rMineur = max(0.1, tau - float(k) * pas) * pulsionMembrane;

        vec3 pLocal = p;
        pLocal.xy *= matriceRotation2D(-angleRot);
        pLocal.z = abs(pLocal.z) - rMajeur;

        float dist = distanceTore(pLocal, rMajeur, rMineur);
        dMin = min(dMin, dist);
    }

    return dMin;
}

vec3 calculerNormale(vec3 p) {
    vec2 e = vec2(0.02, 0.0);
    return normalize(vec3(
        carteScene(p + e.xyy) - carteScene(p - e.xyy),
        carteScene(p + e.yxy) - carteScene(p - e.yxy),
        carteScene(p + e.yyx) - carteScene(p - e.yyx)
    ));
}

float calculerAO(vec3 pos, vec3 nor) {
    float occ = 0.0;
    float sca = 1.0;
    for(int i = 0; i < 4; i++) {
        float h = 0.05 + 0.12 * float(i);
        float d = carteScene(pos + h * nor);
        occ += (h - d) * sca;
        sca *= 0.8;
    }
    return clamp(1.0 - 1.5 * occ, 0.0, 1.0);
}

float bruitBasseFreq(vec2 p) {
    return sin(p.x) * sin(p.y);
}

float nebuleuse(vec3 rd) {
    vec2 p = rd.xy * 2.5;
    mat2 m = mat2(0.8, 0.6, -0.6, 0.8);
    float f = 0.0;
    f += 0.5000 * bruitBasseFreq(p); p = m * p * 2.02;
    f += 0.2500 * bruitBasseFreq(p); p = m * p * 2.03;
    f += 0.1250 * bruitBasseFreq(p); p = m * p * 2.01;
    f += 0.0625 * bruitBasseFreq(p);
    return clamp(f * 0.5 + 0.5, 0.0, 1.0);
}

vec3 genererFondEspace(vec3 dir, vec2 uv) {
    float treble = texture(iChannel0, vec2(0.7, 0.25)).x;

    vec3 colAbsolue = vec3(0.005, 0.008, 0.015);

    vec3 dirParallaxe = dir;
    dirParallaxe.xy += uv * 0.08;

    vec3 dirNeb = dirParallaxe;
    dirNeb.xy *= matriceRotation2D(iTime * 0.02);
    float neb1 = nebuleuse(dirNeb * 1.5 + vec3(1.2, 3.4, 0.0));
    float neb2 = nebuleuse(dirNeb * 2.5 - vec3(4.5, 1.1, 0.0));

    vec3 colNeb1 = vec3(0.15, 0.05, 0.3) * pow(neb1, 2.0);
    vec3 colNeb2 = vec3(0.02, 0.12, 0.25) * pow(neb2, 2.5);

    vec3 dirEtoilesLointaines = dir;
    dirEtoilesLointaines.xy += uv * 0.02;
    dirEtoilesLointaines.xy *= matriceRotation2D(iTime * 0.005);
    vec3 pEtoiles1 = floor(dirEtoilesLointaines * 450.0);
    float valRand1 = fract(sin(dot(pEtoiles1, vec3(12.9898, 78.233, 45.5432))) * 43758.5453);

    float etoilesLointaines = 0.0;
    if (valRand1 > 0.991) {
        float scintille = sin(iTime * 3.0 + valRand1 * 6.28) * 0.5 + 0.5;
        etoilesLointaines = pow((valRand1 - 0.991) / 0.009, 5.0) * (0.5 + 0.5 * scintille) * 0.6;
    }

    vec3 dirEtoilesProches = dir;
    dirEtoilesProches.xy += uv * 0.12;
    dirEtoilesProches.xy *= matriceRotation2D(iTime * 0.015);
    vec3 pEtoiles2 = floor(dirEtoilesProches * 220.0);
    float valRand2 = fract(sin(dot(pEtoiles2, vec3(39.3461, 11.135, 83.211))) * 23421.6312);

    float etoilesProches = 0.0;
    if (valRand2 > 0.982) {
        float scintille = sin(iTime * (6.0 + treble * 12.0) + valRand2 * 6.28) * 0.5 + 0.5;
        etoilesProches = pow((valRand2 - 0.982) / 0.018, 7.0) * (0.7 + 0.3 * scintille) * (1.0 + treble * 0.8);
    }

    vec3 colEtoiles = mix(vec3(0.7, 0.85, 1.0), vec3(1.0, 0.75, 0.5), fract(valRand1 * 10.0)) * etoilesLointaines;
    colEtoiles += mix(vec3(1.0, 0.9, 0.8), vec3(0.6, 0.8, 1.0), fract(valRand2 * 10.0)) * etoilesProches;

    return colAbsolue + colNeb1 + colNeb2 + colEtoiles;
}

void mainImage(out vec4 couleurFragment, in vec2 coordonneesFragment) {
    vec2 resolution = iResolution.xy;
    vec2 uv = (coordonneesFragment - 0.5 * resolution) / resolution.y;
    vec2 q = coordonneesFragment / resolution;

    float bass = texture(iChannel0, vec2(0.02, 0.25)).x;
    float kick = pow(bass, 2.5) * 1.8;

    vec3 orig = vec3(0.0, 0.0, 468.0);
    vec3 dir = normalize(vec3(uv * 0.8, -1.0));

    float distTot = 0.0;
    vec3 colAcc = vec3(0.0);
    float trans = 1.0;

    vec3 posLum1 = vec3(540.0, 540.0, 540.0);
    vec3 posLum2 = vec3(-400.0, -300.0, -200.0);
    vec3 colFond = genererFondEspace(dir, uv);

    for (int i = 0; i < 48; i++) {
        vec3 p = orig + dir * distTot;
        float d = carteScene(p);

        if (d < 0.5) {
            vec3 norm = calculerNormale(p);
            vec3 lDir1 = normalize(posLum1 - p);
            vec3 lDir2 = normalize(posLum2 - p);

            float diff1 = max(dot(norm, lDir1), 0.0);
            float diff2 = max(dot(norm, lDir2), 0.0);

            vec3 viewDir = normalize(-dir);
            vec3 refDir = reflect(-lDir1, norm);
            float spec = pow(max(dot(viewDir, refDir), 0.0), 32.0);

            float ao = calculerAO(p, norm);

            vec3 pal = 0.5 + 0.5 * cos(iTime * 0.2 + vec3(0.0, 2.0, 4.0) + p.z * 0.005);
            vec3 matCol = mix(vec3(0.3, 0.5, 0.9), pal, 0.6);
            matCol += vec3(0.3, 0.1, 0.05) * kick;

            vec3 eclairage = matCol * (vec3(0.15) * ao + vec3(0.8, 0.7, 0.6) * diff1 * ao + vec3(0.2, 0.4, 0.5) * diff2);
            eclairage += vec3(1.0, 0.9, 0.8) * spec * (0.8 + kick * 0.4);

            float densite = clamp((0.5 - d) * 2.0, 0.0, 1.0);
            colAcc += eclairage * densite * trans;
            trans *= (1.0 - densite * 0.6);

            if (trans < 0.01) break;
            distTot += max(d, 0.8);
        } else {
            distTot += d * 0.75;
        }

        if (distTot > 1200.0) break;
    }

    vec3 colFin = mix(colFond, colAcc, 1.0 - trans);

    float lueurBord = smoothstep(0.0, 250.0, distTot) * (1.0 - trans);
    vec3 couleurAura = vec3(0.08, 0.18, 0.35) + vec3(0.2, 0.05, 0.1) * kick;
    colFin += couleurAura * lueurBord * (0.4 + kick * 0.3);

    float facteurBrouillard = 1.0 - exp(-0.0022 * distTot);
    colFin = mix(colFin, colFond, facteurBrouillard);

    colFin = pow(colFin, vec3(0.4545));
    colFin *= 0.5 + 0.5 * pow(16.0 * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.25);

    couleurFragment = vec4(colFin, 1.0);
}
